import { createContext, useContext, useEffect, useMemo, type ReactNode } from "react";
import type { UiLanguage } from "./types";
import backendMessages from "./backend-messages.json";

const backendCatalogue: Record<string, { en: string; ja: string }> = Object.fromEntries(
  Object.entries(backendMessages).map(([en, entry]) => [entry.code, { en, ja: entry.ja }]),
);
for (const [code, entry] of Object.entries(backendCatalogue)) {
  if (!code.startsWith("ai_") || code.includes("__")) continue;
  for (const [endingCode, ending] of Object.entries(backendCatalogue)) {
    if (!endingCode.startsWith("outcome_")) continue;
    backendCatalogue[`${code}__${endingCode.slice("outcome_".length)}`] = { en: `${entry.en} ${ending.en}`, ja: `${entry.ja} ${ending.ja}` };
  }
}
const backendByEnglish = new Map(Object.values(backendCatalogue).map((entry) => [entry.en, entry]));
const backendTemplates = Object.entries(backendCatalogue).filter(([, entry]) => entry.en.includes("{")).map(([code, entry]) => {
  const names: string[] = [];
  const pattern = entry.en.split(/(\{[^{}]*\})/g).map((part) => {
    if (part.startsWith("{") && part.endsWith("}")) { names.push(part.slice(1, -1) || String(names.length)); return "([\\s\\S]*?)"; }
    return part.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }).join("");
  return { code, entry, names, pattern: new RegExp(`^${pattern}$`) };
});

